const intakeRows = $('Sheet: Read Timesheet_Intake').all().map((i) => i.json);
const exportRows = $('Sheet: Read Worker_Export').all().map((i) => i.json);
const threshold = 0.25;

function norm(name) {
  return (name || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').trim();
}

function score(a, b) {
  if (!a || !b) return 0;
  if (a === b) return 100;
  if (a.includes(b) || b.includes(a)) return 80;
  const aw = new Set(a.split(' ').filter(Boolean));
  const bw = new Set(b.split(' ').filter(Boolean));
  let overlap = 0;
  for (const w of aw) if (bw.has(w)) overlap++;
  return overlap * 15;
}

const results = [];
let flaggedCount = 0;
let matchedCount = 0;
let unmatchedCount = 0;

for (const row of intakeRows) {
  const status = (row.status || '').toLowerCase();
  if (status === 'flagged' || status === 'reconciled') continue;

  const worker = norm(row.worker_name);
  let best = null;
  let bestScore = 0;
  for (const exp of exportRows) {
    const s = score(worker, norm(exp.worker_name || exp.name));
    if (s > bestScore) {
      bestScore = s;
      best = exp;
    }
  }

  const intakeHours = Number(row.total_hours) || 0;
  const exportHours = best ? (Number(best.total_hours || best.hours) || 0) : 0;
  const diff = Math.abs(intakeHours - exportHours);

  if (!best || bestScore < 40) {
    unmatchedCount++;
    results.push({
      json: {
        ...row,
        status: 'flagged',
        flagged_reason: 'No matching worker in Worker_Export',
        export_hours: 0,
        hour_difference: intakeHours,
        match_score: bestScore,
        reconciled_at: $now.toISO(),
      },
    });
    flaggedCount++;
    continue;
  }

  matchedCount++;
  if (diff > threshold) {
    flaggedCount++;
    results.push({
      json: {
        ...row,
        status: 'flagged',
        flagged_reason: 'Hour discrepancy ' + diff.toFixed(2) + ' hr (intake ' + intakeHours + ' vs export ' + exportHours + ')',
        export_hours: exportHours,
        hour_difference: diff,
        match_score: bestScore,
        reconciled_at: $now.toISO(),
      },
    });
  } else {
    results.push({
      json: {
        ...row,
        status: 'reconciled',
        flagged_reason: '',
        export_hours: exportHours,
        hour_difference: diff,
        match_score: bestScore,
        reconciled_at: $now.toISO(),
      },
    });
  }
}

if (!results.length) {
  return [{
    json: {
      summary_text: '*Staffing Reconciliation* — No pending intake rows to reconcile.',
      flagged_count: 0,
      matched_count: 0,
      unmatched_count: 0,
      has_updates: false,
    },
  }];
}

const summaryLines = [
  '*Staffing Timesheet Reconciliation* (' + $now.toFormat('yyyy-MM-dd HH:mm') + ')',
  'Reviewed: ' + results.length,
  'Matched: ' + matchedCount,
  'Flagged: ' + flaggedCount,
  'Unmatched workers: ' + unmatchedCount,
  '',
];

const flagged = results.filter((r) => r.json.status === 'flagged');
for (const r of flagged.slice(0, 10)) {
  summaryLines.push('- ' + (r.json.worker_name || 'unknown') + ': ' + (r.json.flagged_reason || 'flagged'));
}
if (flagged.length > 10) summaryLines.push('...and ' + (flagged.length - 10) + ' more');

results[0].json.summary_text = summaryLines.join('\n');
results[0].json.flagged_count = flaggedCount;
results[0].json.matched_count = matchedCount;
results[0].json.unmatched_count = unmatchedCount;
results[0].json.has_updates = true;

return results;

const first = $('Match & Flag Discrepancies').first().json;
return [{
  json: {
    summary_text: first.summary_text || 'Staffing reconciliation complete.',
    flagged_count: first.flagged_count || 0,
  },
}];
